var _markdown = "\n\n`CCoronas.h` · `C3dMarkers.h`\n\n光晕与 3D 标记。每帧重新 `Register` / `Place`（引擎槽位语义）；id 固定便于更新。\n\n## 注册光晕 [#注册光晕]\n\n<Api name=\"CCoronas::RegisterCorona\">\n  按类型或纹理。\n\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      static void RegisterCorona(unsigned int id, CEntity* attachTo, unsigned char red, unsigned char green, unsigned char blue,\n          unsigned char alpha, CVector const& posn, float radius, float farClip, eCoronaType coronaType, eCoronaFlareType flaretype,\n          bool enableReflection, bool checkObstacles, int _param_not_used, float angle, bool longDistance, float nearClip,\n          unsigned char fadeState, float fadeSpeed, bool onlyFromBelow, bool reflectionDelay);\n      // 另有 RwTexture* 重载\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      // 每帧 drawing / 合适钩子：\n      // CCoronas::RegisterCorona(myId, nullptr, 255, 200, 50, 255, pos, 1.0f, 150.0f, type, flare, ...);\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 更新光晕坐标 [#更新光晕坐标]\n\n<Api name=\"UpdateCoronaCoors\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      static void UpdateCoronaCoors(unsigned int id, CVector const& posn, float farClip, float angle);\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      // CCoronas::UpdateCoronaCoors(myId, pos, 150.0f, 0.0f);\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 放 3D 标记 [#放-3d-标记]\n\n<Api name=\"PlaceMarker / PlaceMarkerSet / PlaceMarkerCone\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      static C3dMarker* PlaceMarker(unsigned int id, unsigned short type, CVector& posn, float size,\n          unsigned char red, unsigned char green, unsigned char blue, unsigned char alpha,\n          unsigned short pulsePeriod, float pulseFraction, short rotateRate,\n          float nrm_x, float nrm_y, float nrm_z, bool zCheck);\n      static void PlaceMarkerSet(unsigned int id, unsigned short type, CVector& posn, float size,\n          unsigned char red, unsigned char green, unsigned char blue, unsigned char alpha,\n          unsigned short pulsePeriod, float pulseFraction, short rotateRate);\n      static void PlaceMarkerCone(unsigned int id, CVector& posn, float size,\n          unsigned char red, unsigned char green, unsigned char blue, unsigned char alpha,\n          unsigned short pulsePeriod, float pulseFraction, short rotateRate, unsigned char bEnableCollision);\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      CVector p = FindPlayerCoors();\n      p.z += 1.0f;\n      // C3dMarkers::PlaceMarkerSet(1, type, p, 1.0f, 255, 0, 0, 255, 1024, 0.2f, 0);\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 方向箭头 [#方向箭头]\n\n<Api name=\"DirectionArrowSet\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      static void DirectionArrowSet(CVector posn, float size, int red, int green, int blue, int alpha,\n          float dir_x, float dir_y, float dir_z);\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      // C3dMarkers::DirectionArrowSet(pos, 1.0f, 255, 255, 0, 255, 0, 1, 0);\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 用户标记 [#用户标记]\n\n<Api name=\"User3dMarkerDelete / User3dMarkerDeleteAll\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      static void User3dMarkerDelete(int slotIndex);\n      static void User3dMarkerDeleteAll();\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      // C3dMarkers::User3dMarkerDeleteAll();\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 强制渲染 [#强制渲染]\n\n<Api name=\"ForceRender / IgnoreRenderLimit\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      static void ForceRender(unsigned char bEnable);\n      static bool& IgnoreRenderLimit;\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      C3dMarkers::ForceRender(1);\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n雷达 2D blip 见 [CRadar](/docs/plugins/entities/radar)。\n";
